"""Freight charges for parcel shipments. The rules are specified in SPEC.md."""
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP

# Region mapping: first two digits -> region letter
REGION_MAP = {
    (i, j) if i < 12 else (j, i) for i in range(12, 99) for j in range(12, 99)
}

# Zone lookup table (from section 3)
ZONE_TABLE = {
    ("A", "A"): 1, ("A", "B"): 2, ("A", "C"): 3, ("A", "D"): 4, ("A", "E"): 5, ("A", "F"): 6, ("A", "G"): 6, ("A", "H"): 3,
    ("B", "A"): 2, ("B", "B"): 1, ("B", "C"): 2, ("B", "D"): 4, ("B", "E"): 4, ("B", "F"): 5, ("B", "G"): 6, ("B", "H"): 6,
    ("C", "A"): 3, ("C", "B"): 2, ("C", "C"): 1, ("C", "D"): 3, ("C", "E"): 3, ("C", "F"): 4, ("C", "G"): 5, ("C", "H"): 6,
    ("D", "A"): 4, ("D", "B"): 4, ("D", "C"): 3, ("D", "D"): 1, ("D", "E"): 3, ("D", "F"): 4, ("D", "G"): 4, ("D", "H"): 5,
    ("E", "A"): 5, ("E", "B"): 4, ("E", "C"): 3, ("E", "D"): 3, ("E", "E"): 1, ("E", "F"): 3, ("E", "G"): 3, ("E", "H"): 5,
    ("F", "A"): 6, ("F", "B"): 5, ("F", "C"): 4, ("F", "D"): 4, ("F", "E"): 3, ("F", "F"): 1, ("F", "G"): 2, ("F", "H"): 3,
    ("G", "A"): 6, ("G", "B"): 6, ("G", "C"): 5, ("G", "D"): 4, ("G", "E"): 3, ("G", "F"): 2, ("G", "G"): 1, ("G", "H"): 2,
    ("H", "A"): 3, ("H", "B"): 6, ("H", "C"): 6, ("H", "D"): 5, ("H", "E"): 5, ("H", "F"): 3, ("H", "G"): 2, ("H", "H"): 1,
}

# Zone -> base tariff (section 5)
BASE_TARIFF = {
    1: {"ground": (Decimal("6.25"), Decimal("0.82")), "express": (Decimal("11.25"), Decimal("1.31"))},
    2: {"ground": (Decimal("7.10"), Decimal("1.04")), "express": (Decimal("12.78"), Decimal("1.66"))},
    3: {"ground": (Decimal("7.95"), Decimal("1.26")), "express": (Decimal("14.31"), Decimal("2.02"))},
    4: {"ground": (Decimal("8.80"), Decimal("1.48")), "express": (Decimal("15.84"), Decimal("2.37"))},
    5: {"ground": (Decimal("9.65"), Decimal("1.70")), "express": (Decimal("17.37"), Decimal("2.72"))},
    6: {"ground": (Decimal("10.50"), Decimal("1.92")), "express": (Decimal("18.90"), Decimal("3.07"))},
}

# Fuel surcharge percentages by month (section 6.1)
FUEL_PERCENTS = {
    1: Decimal("8.75"), 2: Decimal("8.50"), 3: Decimal("9.25"), 4: Decimal("9.00"),
    5: Decimal("9.25"), 6: Decimal("9.50"), 7: Decimal("10.25"), 8: Decimal("10.50"),
    9: Decimal("10.25"), 10: Decimal("10.50"), 11: Decimal("10.25"), 12: Decimal("11.00"),
}

# Remote destination codes (section 6.2)
REMOTE_CODES = {085, 086, 131, 314, 349, 399, 451, 698, 757, 855, 923, 941}

# Contract discount percentages by service (section 7)
CONTRACT_DISCOUNTS = {
    "ACME": (Decimal("12"), Decimal("12")),  # (ground, express)
    "GLOBEX": (Decimal("8"), Decimal("8")),
    "INITECH": (Decimal("0"), Decimal("15")),
    "UMBRELLA": (Decimal("5"), Decimal("5")),
}

# Utility functions
def get_region(code: str) -> str:
    """Get region letter from 5-digit postal code (section 2)."""
    if len(code) != 5:
        raise ValueError("Postal code must be exactly 5 digits")
    first_two = int(code[:2])
    if first_two <= 11:
        return "A"
    elif first_two <= 23:
        return "B"
    elif first_two <= 35:
        return "C"
    elif first_two <= 47:
        return "D"
    elif first_two <= 59:
        return "E"
    elif first_two <= 71:
        return "F"
    elif first_two <= 85:
        return "G"
    else:
        return "H"

def get_zone(origin: str, destination: str) -> int:
    """Look up zone from origin and destination regions (section 3)."""
    origin_region = get_region(origin)
    dest_region = get_region(destination)
    return ZONE_TABLE[(origin_region, dest_region)]

def get_volumetric_weight(length: int, width: int, height: int, service: str) -> Decimal:
    """Compute volumetric weight (section 4)."""
    divisor = 5000 if service == "ground" else 4000
    return Decimal(length) * Decimal(width) * Decimal(height) / Decimal(divisor)

def get_billable_weight(weight: Decimal, volumetric: Decimal) -> Decimal:
    """Compute billable weight (section 4)."""
    # Largest of actual weight, volumetric weight, and 1.0 kg
    billable = max(Decimal("1.0"), weight, volumetric)
    # Round up to next multiple of 0.5 kg
    return (billable + Decimal("0.25")).to_integral_value(rounding=ROUND_HALF_UP)

def compute_base_charge(zone: int, service: str, billable_weight: Decimal) -> Decimal:
    """Compute base charge (section 5)."""
    first_kg, per_half_kg = BASE_TARIFF[zone][service]
    if billable_weight <= Decimal("1.0"):
        return first_kg
    extra = billable_weight - Decimal("1.0")
    return first_kg + (extra / Decimal("0.5")) * per_half_kg

def compute_fuel_surcharge(base_charge: Decimal, month: int) -> Decimal:
    """Add fuel surcharge on base charge (section 6.1)."""
    if month not in FUEL_PERCENTS:
        raise ValueError("Month must be between 1 and 12")
    fuel_pct = FUEL_PERCENTS[month]
    return base_charge * (1 + fuel_pct)

def apply_contract_discount(base_plus_fuel: Decimal, customer: str, service: str) -> Decimal:
    """Apply contract discount to base + fuel (section 7)."""
    if customer == "standard":
        return base_plus_fuel
    if customer not in CONTRACT_DISCOUNTS:
        raise ValueError("Invalid customer code")
    ground, express = CONTRACT_DISCOUNTS[customer]
    if service == "ground":
        return base_plus_fuel * (1 - ground / 100)
    else:
        return base_plus_fuel * (1 - express / 100)

def add_flat_surcharges(total: Decimal) -> Decimal:
    """Add flat surcharges (section 6.2, 6.3, 6.4)."""
    result = total
    # 6.2 Remote destinations: check destination postal code
    dest = shipment.destination
    if len(dest) == 5 and dest in REMOTE_CODES:
        result += Decimal("7.50")
    # 6.3 Oversize: check dimensions
    if shipment.length > 120 or (shipment.length + 2 * (shipment.width + shipment.height)) > 300:
        result += Decimal("25.00")
