import type { Page, Task, TaskQuery } from "./types.ts";
import { TASKS } from "./store.ts";
import { ValidationError } from "./errors.ts";

/** Filters, sorts and paginates tasks as described in README.md ("Listing tasks"). */
export function listTasks(query: TaskQuery, tasks: readonly Task[] = TASKS): Page<Task> {
  let filtered = tasks;

  // Validate and apply filters
  if (query.status !== undefined) {
    const statuses = query.status.split(/[\s,]+/).filter(Boolean);
    filtered = filtered.filter((t) => statuses.includes(t.status));
  }

  if (query.assignee !== undefined) {
    if (query.assignee === "none") {
      filtered = filtered.filter((t) => t.assignee === null);
    } else {
      filtered = filtered.filter((t) => t.assignee === query.assignee);
    }
  }

  if (query.tag !== undefined) {
    filtered = filtered.filter((t) => t.tags.includes(query.tag));
  }

  if (query.q !== undefined && query.q.trim() !== "") {
    filtered = filtered.filter((t) => t.title.toLowerCase().includes(query.q.toLowerCase()));
  }

  // Validate and apply sorting
  if (query.sort !== undefined) {
    const [field, direction] = query.sort.split(":");
    let comparator: (a: Task, b: Task) => number;

    switch (field) {
      case "dueDate":
        comparator = (a, b) => {
          if (a.dueDate === null && b.dueDate === null) {
            return 0;
          }
          if (a.dueDate === null) {
            return direction === "asc" ? 1 : -1;
          }
          if (b.dueDate === null) {
            return direction === "asc" ? -1 : 1;
          }
          if (a.dueDate < b.dueDate) {
            return direction === "asc" ? -1 : 1;
          }
          if (a.dueDate > b.dueDate) {
            return direction === "asc" ? 1 : -1;
          }
          return 0;
        };
      case "priority":
        comparator = (a, b) => {
          if (a.priority !== b.priority) {
            return direction === "asc" ? a.priority - b.priority : b.priority - a.priority;
          }
          // Tie-breaker: id ascending
          return direction === "asc" ? a.id - b.id : b.id - a.id;
        };
      case "title":
        comparator = (a, b) => {
          if (a.title.toLowerCase() !== b.title.toLowerCase()) {
            return direction === "asc" ? a.title.toLowerCase().localeCompare(b.title.toLowerCase()) : b.title.toLowerCase().localeCompare(a.title.toLowerCase());
          }
          // Tie-breaker: id ascending
          return direction === "asc" ? a.id - b.id : b.id - a.id;
        };
      default:
        throw new ValidationError("sort", query.sort);
    }

    filtered.sort(comparator);
  }

  // Validate and apply pagination
  const page = parseInt(query.page || "1", 10);
  const pageSize = parseInt(query.pageSize || "20", 10);

  if (page < 1 || page > 100) {
    throw new ValidationError("page", query.page);
  }
  if (pageSize < 1 || pageSize > 100) {
    throw new ValidationError("pageSize", query.pageSize);
  }

  const start = (page - 1) * pageSize;
  const end = start + pageSize;
  const items = filtered.slice(start, end);
  const total = filtered.length;

  return {
    items,
    total,
    page,
    pageSize,
  };
}

