app.MapPut("/products/{id:int}", (int id, ProductInput input, ProductStore store) =>
{
    var errors = ProductValidation.Validate(input);
    if (errors.Count > 0) return Results.ValidationProblem(errors);

    var product = store.Find(id);
    if (product is null) return Results.NotFound();

    if (input.Version is null) return Results.BadRequest();

    if (input.Version != product.Version) return Results.Conflict();

    var updatedProduct = new Product(
        product.Id,
        input.Name!.Trim(),
        input.Price,
        input.Stock,
        product.Version + 1
    );

    store(products[product.Id] = updatedProduct);
    return Results.Ok(updatedProduct);
});

